<script>const accountTrigger=document.getElementById('accountTrigger'),accountDropdown=document.getElementById('accountDropdown');function closeAccountMenu(){accountDropdown.classList.remove('show');accountTrigger.classList.remove('active');accountTrigger.setAttribute('aria-expanded','false')}accountTrigger.addEventListener('click',event=>{event.stopPropagation();const isOpen=accountDropdown.classList.toggle('show');accountTrigger.classList.toggle('active',isOpen);accountTrigger.setAttribute('aria-expanded',String(isOpen))});document.addEventListener('click',event=>{if(!accountDropdown.contains(event.target)&&!accountTrigger.contains(event.target))closeAccountMenu()});document.addEventListener('keydown',event=>{if(event.key==='Escape')closeAccountMenu()});</script></body></html>
